import React, { useState, useEffect } from 'react';
import { Stage, Layer, Rect, Text } from 'react-konva';

const DesignCanvas = ({ projectData }) => {
  const [elements, setElements] = useState(projectData.elements || []);

  const handleDragEnd = (e, index) => {
    const newElements = [...elements];
    newElements[index] = {
      ...newElements[index],
      x: e.target.x(),
      y: e.target.y(),
    };
    setElements(newElements);
    // TODO: Send update to backend via WebSocket
  };

  return (
    <Stage width={window.innerWidth} height={window.innerHeight}>
      <Layer>
        {elements.map((el, i) => (
          <Rect
            key={el.id}
            x={el.x}
            y={el.y}
            width={el.width}
            height={el.height}
            fill={el.fill}
            draggable
            onDragEnd={(e) => handleDragEnd(e, i)}
          />
        ))}
      </Layer>
    </Stage>
  );
};
